package mx.com.tiendaonline;import mx.com.tiendaonline.cliente.model.dto.command.ClienteCreateCommand;import mx.com.tiendaonline.cliente.model.entity.Cliente;import mx.com.tiendaonline.cliente.port.dao.ClienteDAO;import mx.com.tiendaonline.cliente.port.event.ClienteEventCreate;import mx.com.tiendaonline.cliente.port.repository.ClienteRepository;import mx.com.tiendaonline.cliente.service.ClienteCreateService;import mx.com.tiendaonline.compraproducto.port.repository.CompraRespository;import mx.com.tiendaonline.compraproducto.service.StockService;import mx.com.tiendaonline.producto.model.dto.command.ProductoCreateCommand;import mx.com.tiendaonline.producto.model.entity.Producto;import mx.com.tiendaonline.producto.model.entity.ProductoId;import mx.com.tiendaonline.producto.port.dao.ProductoDAO;import mx.com.tiendaonline.producto.port.repository.ProductoRepository;import mx.com.tiendaonline.producto.service.ProductoCreateService;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.ArgumentMatchers.anyString;import static org.mockito.Mockito.verify;import static org.mockito.Mockito.when;@ExtendWith(MockitoExtension.class)public class ProductoCreateServiceTest {    @Mock    private ProductoRepository productoRepository;    @Mock    private ProductoDAO productoDAO;    @Mock    private CompraRespository compraRespository;    @Mock    private StockService stockService;    @InjectMocks    private ProductoCreateService productoCreateService;    @Test    void crearProductoTest(){        ProductoCreateCommand producto= new ProductoCreateCommand(null,"xbox", BigDecimal.valueOf(9000.00),10);        Producto productoGuardado = new Producto(1L,"xbox",BigDecimal.valueOf(9000.00),10);        when (productoRepository.create(any(Producto.class))).thenReturn(productoGuardado);        Producto resultado = productoCreateService.crear(producto);        assertNotNull(resultado);        assertEquals(1L,resultado.getId());        assertEquals("xbox",resultado.getNombre());        assertEquals(BigDecimal.valueOf(9000.00), resultado.getPrecio());        assertEquals(10, resultado.getStock());        verify(productoRepository).create(any(Producto.class));    }    @Test    void crearCompraCorrectamente(){        Long id = 1L;        String nombre ="Laptop";        BigDecimal precio = new BigDecimal("20000");        Integer stock = 10;        Producto producto =  new Producto(id,nombre,precio,stock);        assertNotNull(producto.getId());        assertEquals(id,                producto.getId());        assertEquals(nombre,producto.getNombre());        assertEquals(precio,producto.getPrecio());        assertEquals(stock,producto.getStock());    }}